<span class="line">        <span class="token class-name">Err</span><span class="token punctuation">::</span><span class="token operator">&lt;</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> _<span class="token operator">&gt;</span><span class="token punctuation">(</span></span>
